INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann ich im dualen System nur im Betrieb lernen?', 2, '[{"text": "Nein", "correct": true, "because": "Berufsschule ist Teil davon"}, {"text": "Ja", "correct": false, "because": "Dual heißt Betrieb und Schule"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ich im dualen System eine Abschlussprüfung machen?', 2, '[{"text": "Ja", "correct": true, "because": "Pflicht zur Qualifikation"}, {"text": "Nein", "correct": false, "because": "Prüfung ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Betrieb im dualen System für meine Theorie verantwortlich?', 2, '[{"text": "Nein", "correct": true, "because": "Theorie in der Berufsschule"}, {"text": "Ja", "correct": false, "because": "Betrieb macht Praxis"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich im dualen System früher fertig werden?', 2, '[{"text": "Ja", "correct": true, "because": "Verkürzung bei guten Leistungen"}, {"text": "Nein", "correct": false, "because": "Flexibilität möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Gibt’s im dualen System Zwischenprüfungen?', 2, '[{"text": "Ja", "correct": true, "because": "Fortschritt wird geprüft"}, {"text": "Nein", "correct": false, "because": "Zwischenprüfung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das duale System nur in der IT genutzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Viele Branchen nutzen es"}, {"text": "Ja", "correct": false, "because": "Nicht IT-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Ablauf im dualen System für alle gleich?', 2, '[{"text": "Nein", "correct": true, "because": "Je nach Beruf unterschiedlich"}, {"text": "Ja", "correct": false, "because": "Variiert nach Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich im dualen System ohne Berufsschule auskommen?', 2, '[{"text": "Nein", "correct": true, "because": "Schule ist Pflichtbestandteil"}, {"text": "Ja", "correct": false, "because": "Dualität erfordert beides"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Wer organisiert die Prüfungen im dualen System?', 2, '[{"text": "IHK", "correct": true, "because": "Industrie- und Handelskammer zuständig"}, {"text": "Betrieb", "correct": false, "because": "Nur Ausbildung"}, {"text": "Azubi", "correct": false, "because": "Keine Eigenverantwortung"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin sagt, ich muss bald eine Prüfung schreiben. Welche könnte das sein?', 3, '[{"text": "Zwischenprüfung", "correct": true, "because": "Kontrolliert Fortschritt"}, {"text": "Eingangstest", "correct": false, "because": "Vor Ausbildung"}, {"text": "Führerschein", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist der Hauptbestandteil des dualen Systems?', 2, '[{"text": "Praxis und Theorie", "correct": true, "because": "Kombination ist Kern"}, {"text": "Nur Praxis", "correct": false, "because": "Schule fehlt"}, {"text": "Nur Theorie", "correct": false, "because": "Betrieb fehlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt, wann meine Abschlussprüfung ist. Was antworte ich?', 3, '[{"text": "Ende der Ausbildung", "correct": true, "because": "Regulärer Zeitpunkt"}, {"text": "Nach einem Monat", "correct": false, "because": "Zu früh"}, {"text": "Wann ich will", "correct": false, "because": "Festgelegt"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was gehört zum Aufbau des dualen Systems?', 4, '[{"text": "Betrieb", "correct": true, "because": "Praxisort"}, {"text": "Berufsschule", "correct": true, "because": "Theorieort"}, {"text": "Prüfungen", "correct": true, "because": "Abschluss"}, {"text": "Universität", "correct": false, "because": "Kein Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gibt’s im Ablauf des dualen Systems?', 3, '[{"text": "Einführung", "correct": true, "because": "Startphase"}, {"text": "Lernphase", "correct": true, "because": "Hauptteil"}, {"text": "Prüfungsphase", "correct": true, "because": "Abschluss"}, {"text": "Urlaubsphase", "correct": false, "because": "Kein Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir haben bald eine Prüfung. Was könnte geprüft werden?', 3, '[{"text": "Fachwissen", "correct": true, "because": "Theorie geprüft"}, {"text": "Praktische Fertigkeiten", "correct": true, "because": "Praxis geprüft"}, {"text": "Berichtsheft", "correct": true, "because": "Dokumentation"}, {"text": "Sportlichkeit", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Institutionen sind am dualen System beteiligt?', 4, '[{"text": "Betrieb", "correct": true, "because": "Praxisanbieter"}, {"text": "Berufsschule", "correct": true, "because": "Theorieanbieter"}, {"text": "IHK", "correct": true, "because": "Prüfungsorganisator"}, {"text": "Supermarkt", "correct": false, "because": "Kein Bezug"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das duale System kombiniert Betrieb und Schule. b) Prüfungen gibt’s nur am Ende.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kombination ja, Zwischenprüfungen auch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Ablauf ist gesetzlich geregelt. b) Die Berufsschule ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Regelung ja, Schule Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zwischenprüfungen prüfen den Lernfortschritt. b) Der Betrieb macht alle Prüfungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fortschritt ja, IHK prüft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das duale System dauert meist 3 Jahre. b) Verkürzung ist unmöglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "3 Jahre üblich, Verkürzung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');